def preorder(root):
    out = []

    def walk(node):
        if node is None:
            return
        out.append(node.val)   # root
        walk(node.left)        # left
        walk(node.right)       # right

    walk(root)
    return out

def preorder(root):
    if root is None:
        return []
    out, stack = [], [root]
    while stack:
        node = stack.pop()
        out.append(node.val)
        if node.right is not None:
            stack.append(node.right)   # pushed first, popped second
        if node.left is not None:
            stack.append(node.left)
    return out

def preorder(root):
    out, node = [], root
    while node is not None:
        if node.left is None:
            out.append(node.val)
            node = node.right
            continue
        pred = node.left
        while pred.right is not None and pred.right is not node:
            pred = pred.right
        if pred.right is None:
            out.append(node.val)   # emit before descending: preorder
            pred.right = node      # thread
            node = node.left
        else:
            pred.right = None      # unthread, left subtree done
            node = node.right
    return out
